# ==============================================================================# 073_EVENT_CERTIFICATION_ENGINE.py## IOTEC EVENT CERTIFICATION ENGINE## Nenhum evento entra no sistema sem comprovação.## ==============================================================================from __future__ import annotationsimport sqlite3import hashlibimport jsonimport socketfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")# ==============================================================================# ENGINE# ==============================================================================class EventCertificationEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS certified_events(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            event_id TEXT,            event_type TEXT,            source TEXT,            agent TEXT,            mission TEXT,            evidence TEXT,            metadata TEXT,            confidence REAL,            certified INTEGER,            reason TEXT,            hostname TEXT,            hash TEXT        )        """)        self.conn.commit()    # --------------------------------------------------------------------------    def _hash(self, payload):        raw = json.dumps(            payload,            sort_keys=True,            ensure_ascii=False        )        return hashlib.sha256(raw.encode()).hexdigest()    # --------------------------------------------------------------------------    def certify(        self,        event_type,        source,        agent,        mission,        evidence,        metadata=None    ):        metadata = metadata or {}        timestamp = datetime.utcnow().isoformat()        event_id = hashlib.md5(            f"{timestamp}{agent}{mission}".encode()        ).hexdigest()        certified = 1        confidence = 100.0        reason = "OK"        if not source:            certified = 0            confidence = 0            reason = "SEM_FONTE"        elif not evidence:            certified = 0            confidence = 0            reason = "SEM_EVIDENCIA"        payload = {            "timestamp": timestamp,            "event_id": event_id,            "event_type": event_type,            "source": source,            "agent": agent,            "mission": mission,            "evidence": evidence,            "metadata": metadata,            "confidence": confidence,            "certified": certified,            "reason": reason,            "hostname": socket.gethostname()        }        assinatura = self._hash(payload)        self.conn.execute("""        INSERT INTO certified_events(            timestamp,            event_id,            event_type,            source,            agent,            mission,            evidence,            metadata,            confidence,            certified,            reason,            hostname,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)        """,        (            payload["timestamp"],            payload["event_id"],            payload["event_type"],            payload["source"],            payload["agent"],            payload["mission"],            payload["evidence"],            json.dumps(                payload["metadata"],                ensure_ascii=False            ),            payload["confidence"],            payload["certified"],            payload["reason"],            payload["hostname"],            assinatura        )        )        self.conn.commit()        payload["hash"] = assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = EventCertificationEngine()    evento = engine.certify(        event_type="MISSION_EVIDENCE",        source="LEAD_CAPTURE_ENGINE",        agent="LEAD_AGENT_001",        mission="Captar empresas",        evidence="Empresa ABC encontrada",        metadata={            "empresa":"Empresa ABC",            "cidade":"Fortaleza",            "setor":"Tecnologia"        }    )    print("="*70)    print("EVENTO CERTIFICADO")    print("="*70)    for k,v in evento.items():        print(f"{k:15}: {v}")    print("="*70)